    private static String slatesPath(long slateId, String suffix) {
        return "/api/v1/dfs/slates/" + slateId + suffix;
    }

    private static String normalizePollPath(Http.RawResponse res, SimJobStatusResponse st, long slateId) {
        String loc = res.headers().firstValue("Location").orElse(null);
        String raw = (loc != null && !loc.isEmpty()) ? loc : (st != null ? st.pollUrl() : null);
        if ((raw == null || raw.isEmpty()) && st != null && st.jobId() != null) {
            raw = slatesPath(slateId, "/sim/jobs/" + URLEncoder.encode(st.jobId(), StandardCharsets.UTF_8));
        }
        if (raw == null || raw.isEmpty()) {
            throw new StatApiException(202, JsonValue.NULL, slatesPath(slateId, "/sim/lineups"),
                "stat-api: 202 response missing Location and poll_url");
        }
        if (raw.startsWith("http://") || raw.startsWith("https://")) {
            URI u = URI.create(raw);
            return u.getRawQuery() != null ? u.getRawPath() + "?" + u.getRawQuery() : u.getRawPath();
        }
        return raw;
    }

    private static Http.RawResponse pollUntilReady(
        Http http,
        long slateId,
        Http.RawResponse initial,
        SimRequestOptions opts,
        boolean expectCsv
    ) {
        if (initial.status() != 202) {
            return initial;
        }
        long timeoutMs = (opts != null && opts.timeout != null) ? opts.timeout.toMillis() : 120_000L;
        long deadlineMs = System.currentTimeMillis() + timeoutMs;
        Http.RawResponse cur = initial;
        while (true) {
            SimJobStatusResponse st = SimJobStatusResponse.fromJson(Json.parse(cur.body()));
            if (st != null && "failed".equals(st.status())) {
                throw new StatApiException(500, Json.parse(cur.body()), String.valueOf(st.pollUrl()),
                    st.error() != null ? st.error() : "SIM job failed");
            }
            String pollPath = normalizePollPath(cur, st, slateId);
            String retryHdr = cur.headers().firstValue("Retry-After").orElse(null);
            long delayMs = 1000L;
            if (retryHdr != null && !retryHdr.isEmpty()) {
                try {
                    delayMs = (long) (Double.parseDouble(retryHdr) * 1000.0);
                } catch (NumberFormatException ignored) {}
            } else if (st != null && st.retryAfterSeconds() != null) {
                delayMs = st.retryAfterSeconds() * 1000L;
            }
            if (opts != null && opts.pollIntervalMillis != null) {
                delayMs = opts.pollIntervalMillis;
            }
            long remaining = deadlineMs - System.currentTimeMillis();
            if (remaining <= 0) {
                throw new NotReadyException(202, Json.parse(cur.body()), pollPath, retryHdr);
            }
            long sleepMs = Math.max(0L, Math.min(delayMs, remaining));
            if (sleepMs > 0) {
                try {
                    Thread.sleep(sleepMs);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                    throw new StatApiException(0, JsonValue.NULL, pollPath, "Interrupted while polling SIM job");
                }
            }
            Map<String, String> headers = expectCsv ? Map.of("Accept", "text/csv, application/json;q=0.9") : Collections.emptyMap();
            Http.RawResponse next = http.rawRequest("GET", pollPath, null, headers, true);
            if (next.status() != 202) {
                return next;
            }
            cur = next;
        }
    }

    public static OptimizerLineupsResponse optimizerLineups(Http http, long slateId, OptimizerLineupsRequest body) {
        String path = slatesPath(slateId, "/optimizer/lineups");
        String payload = body == null ? "{\"response_format\":\"json\"}" : body.toJsonWithFormat("json");
        Http.RawResponse res = http.rawRequest("POST", path, payload, Collections.emptyMap(), false);
        return OptimizerLineupsResponse.fromJson(Json.parse(res.body()));
    }

    public static String optimizerLineupsCsv(Http http, long slateId, OptimizerLineupsRequest body) {
        String path = slatesPath(slateId, "/optimizer/lineups");
        String payload = body == null ? "{\"response_format\":\"csv\"}" : body.toJsonWithFormat("csv");
        Http.RawResponse res = http.rawRequest("POST", path, payload, Map.of("Accept", "text/csv, application/json;q=0.9"), false);
        return res.body();
    }

    public static SimLineupsResponse simLineups(Http http, long slateId, SimLineupsRequest body, SimRequestOptions opts) {
        String path = slatesPath(slateId, "/sim/lineups");
        String payload = body == null ? "{\"response_format\":\"json\"}" : body.toJsonWithFormat("json");
        Map<String, String> headers = (opts != null && opts.wait) ? Map.of("Prefer", "wait") : Collections.emptyMap();
        Http.RawResponse res = pollUntilReady(http, slateId, http.rawRequest("POST", path, payload, headers, false), opts, false);
        return SimLineupsResponse.fromJson(Json.parse(res.body()));
    }

    public static String simLineupsCsv(Http http, long slateId, SimLineupsRequest body, SimRequestOptions opts) {
        String path = slatesPath(slateId, "/sim/lineups");
        String payload = body == null ? "{\"response_format\":\"csv\"}" : body.toJsonWithFormat("csv");
        Map<String, String> headers = new HashMap<>();
        headers.put("Accept", "text/csv, application/json;q=0.9");
        if (opts != null && opts.wait) {
            headers.put("Prefer", "wait");
        }
        Http.RawResponse res = pollUntilReady(http, slateId, http.rawRequest("POST", path, payload, headers, false), opts, true);
        return res.body();
    }

    public static SimJobStatusResponse simLineupsStart(Http http, long slateId, SimLineupsRequest body) {
        String path = slatesPath(slateId, "/sim/lineups");
        String payload = body == null ? "{}" : body.toJson();
        Http.RawResponse res = http.rawRequest("POST", path, payload, Map.of("Prefer", "respond-async"), false);
        return SimJobStatusResponse.fromJson(Json.parse(res.body()));
    }

    public static SimJobPollResult simJob(Http http, long slateId, String jobId) {
        String path = slatesPath(slateId, "/sim/jobs/" + URLEncoder.encode(jobId, StandardCharsets.UTF_8));
        Http.RawResponse res = http.rawRequest("GET", path, null, Map.of("Accept", "application/json, text/csv;q=0.9"), true);
        if (res.status() == 202) {
            return new SimJobPollResult(false, SimJobStatusResponse.fromJson(Json.parse(res.body())), null, null);
        }
        String ct = res.headers().firstValue("Content-Type").orElse("");
        if (ct.contains("text/csv")) {
            return new SimJobPollResult(true, null, null, res.body());
        }
        return new SimJobPollResult(true, null, SimLineupsResponse.fromJson(Json.parse(res.body())), null);
    }

    public static PortfolioSelectResponse simSelectPool(Http http, long slateId, PortfolioSelectRequest body) {
        if (body == null) {
            throw new IllegalArgumentException("PortfolioSelectRequest is required");
        }
        String path = slatesPath(slateId, "/sim/lineups");
        Http.RawResponse res = pollUntilReady(
            http,
            slateId,
            http.rawRequest("POST", path, body.toJsonWithFormat("json"), Collections.emptyMap(), false),
            null,
            false
        );
        return PortfolioSelectResponse.fromJson(Json.parse(res.body()));
    }

    public static LateSwapResponse simLateSwap(Http http, long slateId, LateSwapRequest body, SimRequestOptions opts) {
        if (body == null) {
            throw new IllegalArgumentException("LateSwapRequest is required");
        }
        String path = slatesPath(slateId, "/sim/lineups");
        Map<String, String> headers = (opts != null && opts.wait) ? Map.of("Prefer", "wait") : Collections.emptyMap();
        Http.RawResponse res = pollUntilReady(
            http,
            slateId,
            http.rawRequest("POST", path, body.toJsonWithFormat("json"), headers, false),
            opts,
            false
        );
        return LateSwapResponse.fromJson(Json.parse(res.body()));
    }

